import {SPOTS,STORAGE_KEY,freshState,readState,saveState,borrow,returnUmbrella,toggleFavorite,rateRental,matchesCode,haversine,LOAN_MS,deadline,rentalNow,returnSlots,compensationFor,reportDamage,clearDamage,setOverdueDemo,registerLoan,registerReturn,localDate,qrSpotId} from './model.mjs?v=3.0';
import {icon,umbrellaArt} from './icons.mjs?v=3.0';

import {EN} from './english.mjs?v=3.0';
import {SITE_ORIGIN,stationUrl,qrSvg,downloadQr} from './qr.mjs?v=3.0';
import jsQR from './vendor/jsqr.mjs';

let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('unavailable');}};}
let state=readState(storage),query='',filter='all',view='list',geo=null,selectedMap='koku',rating=0,cameraStream=null,scanTimer=null,scanBusy=false,toastTimer=null,returnTarget=null,cameraRequest=0,verifiedAuth=null,qrSelected='koku';
const root=document.getElementById('app'),dialog=document.getElementById('dialog');
const L=(ja,zh,en)=>state.lang==='en'?(en??EN[zh]??zh):state.lang==='zh'?zh:ja;
const locale=()=>({ja:'ja-JP',zh:'zh-CN',en:'en-GB'})[state.lang];
const field=(s,key)=>state.lang==='en'?s[key+'En']:state.lang==='zh'?s[key+'Zh']:s[key];
const currentOrigin=()=>window.location?.origin?.startsWith('https:')?window.location.origin:SITE_ORIGIN;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=s=>state.lang==='en'?s.en:state.lang==='zh'?s.zh:s.name;
const spot=id=>SPOTS.find(s=>s.id===id)||SPOTS[0];
const stamp=(t,opt={})=>new Intl.DateTimeFormat(locale(),{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',...opt}).format(new Date(t));
const clock=t=>new Intl.DateTimeFormat(locale(),{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(t));
const mins=(a,b=Date.now())=>Math.max(0,Math.floor((b-a)/60000));
const duration=(a,b)=>{const m=mins(a,b);if(state.lang==='en')return m<1?'Less than 1 minute':m<60?`${m} min`:`${Math.floor(m/60)}h ${m%60}m`;return m<1?L('1分未満','不到 1 分钟'):m<60?`${m}${L('分','分钟')}`:`${Math.floor(m/60)}${L('時間','小时')} ${m%60}${L('分','分钟')}`;};
const route=()=>{const [page,params]=location.hash.slice(1).split('?');const query=new URLSearchParams(location.search||'');return {page:page||(query.has('spot')?'station':'home'),params:page?new URLSearchParams(params||''):query};};
function go(page){if(location.hash==='#'+page){render();window.scrollTo(0,0);}else location.hash=page;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function commit(next){state=next;if(!saveState(storage,state))toast(L('保存できません。この画面を閉じるとデータが失われます。','无法保存，关闭页面后数据将丢失。'));}
function error(e){const messages={active:L('すでに傘を利用中です。返却後にお借りください。','你正在借用一把伞，请先归还。'),inactive:L('利用中の傘はありません。','目前没有借用中的伞。'),empty:L('このスポットの傘は貸出中です。','该伞点暂无可借雨伞。'),full:L('返却スペースがありません。別のスポットをお選びください。','该伞点已满，请选择其他归还点。'),favorites:L('お気に入りは最大2つです。1つ解除してから追加してください。','最多收藏两个伞点，请先取消一个收藏。'),rating:L('星を1〜5つ選んでください。','请选择 1–5 星评分。'),auth:L('認証をやり直してください。','请重新完成伞点认证。')};toast(messages[e.message]||L('操作を完了できませんでした。もう一度お試しください。','操作未完成，请重试。'));}
const btn=(text,action,cls='primary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const labelDemo=()=>`<span class="demo-label">${L('デモデータ','演示数据')}</span>`;
function distance(s){const n=geo?haversine(geo,s):s.distance;return n>=1000?`${(n/1000).toFixed(1)} km`:`${n} m`;}
function nearby(list=SPOTS){return [...list].sort((a,b)=>geo?haversine(geo,a)-haversine(geo,b):a.distance-b.distance);}
function avatar(){return esc((state.profile.name||L('ゲスト','访客')).slice(0,1).toUpperCase());}

function methodName(method){return ({'sound-demo':L('音認証（デモ）','声音认证（演示）'),'code':L('コード入力','代码输入'),'qr-demo':L('QR（デモ）','二维码（演示）'),'qr-camera':L('QRカメラ','摄像头扫码'),'qr-link':L('共用QRリンク','共用二维码链接','Shared QR link'),'qr-photo':L('QR画像読取','二维码图片识别','QR image scan'),'legacy':L('旧版の認証','旧版认证')})[method]||L('旧版の認証','旧版认证');}
function policyStrip(){return `<div class="loan-policy-strip"><span>${icon('calendar')}<strong>${L('貸出期間 1週間','借用期限：一周')}</strong></span><p>${L('通常利用は無料。期限超過で未返却・破損の場合は弁償代 ¥2,000。','正常使用免费；逾期未还或损坏，赔偿金额为 ¥2,000。')}</p><button data-action="rules">${L('利用ルール','使用规则')}${icon('chevron')}</button></div>`;}
function policyBox(){return `<div class="policy-box"><div>${icon('calendar')}<strong>${L('貸出期間は1週間','借用期限为一周')}</strong></div><p>${L('1週間を超えて返却できない場合、または傘を壊した場合は弁償代2,000円。両方に当てはまっても1本につき2,000円です。','借用超过一周未归还，或雨伞损坏，赔偿金额为 2,000 日元。两项同时发生时每把伞计一次。')}</p><small>${L('3.0のルールを再現したデモです。実際の請求・決済はありません。','按 3.0 规则演示，不会产生真实账单或扣款。','These are the version 3.0 demo rules. No actual billing or payments occur.')}</small></div>`;}
function dueText(a){const diff=deadline(a)-rentalNow(a),m=Math.ceil(Math.abs(diff)/60000),days=Math.floor(m/1440),hours=Math.floor(m%1440/60),minutes=m%60;const value=days?L(`${days}日 ${hours}時間`,`${days} 天 ${hours} 小时`,`${days}d ${hours}h`):hours?L(`${hours}時間 ${minutes}分`,`${hours} 小时 ${minutes} 分钟`,`${hours}h ${minutes}m`):L(`${minutes}分`,`${minutes} 分钟`,`${minutes} min`);return diff<0?L(`期限超過 ${value}`,`已逾期 ${value}`,`Overdue by ${value}`):L(`返却まで あと${value}`,`距归还还剩 ${value}`,`${value} left to return`);}
function duePanel(a){const cost=compensationFor(a),percent=Math.max(0,Math.min(100,(rentalNow(a)-a.startedAt)/LOAN_MS*100));return `<section class="due-card ${cost.overdue?'overdue':''}"><div class="due-label">${icon('calendar')}<span>${L('返却期限 · 貸出期間1週間','归还期限 · 借用一周')}</span>${a.demoOverdue?`<b>${L('デモ時刻','演示时钟')}</b>`:''}</div><strong class="due-date">${stamp(deadline(a))}</strong><p class="due-remaining">${dueText(a)}</p><div class="due-progress" role="progressbar" aria-label="${L('貸出期間の経過','借用期限进度')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(percent)}"><i style="width:${percent}%"></i></div>${cost.amount?`<div class="due-fee">${icon('alert')}<span>${L('弁償代（デモ）','赔偿金额（演示）')} <b>¥2,000</b><small>${cost.reasons.map(r=>r==='overdue'?L('期限超過','逾期未还'):L('破損申告あり','已申报损坏')).join(' / ')} · ${L('未精算・実請求なし','未结算 · 无真实扣款')}</small></span></div>`:`<small>${L('期限内に破損なく返却すると、利用料金は0円です。','期限内完好归还，使用费用为零。')}</small>`}${a.policyVersion===1?`<p class="legacy-note">${L('旧版で開始したデモ利用です。弁償ルールは次回の貸出から適用します。','这是旧版开始的演示借用，赔偿规则从下次借用起适用。')}</p>`:''}</section>`;}
function rules(){openDialog(`<div class="dialog-icon">${icon('qr')}</div><p class="eyebrow">RAIN FLOW AS · VERSION 3.0</p><h2 id="dialog-title">${L('QRから、かんたん登録。','扫码登记，轻松借还。','Scan, register, and go.')}</h2>${policyBox()}<div class="guide-steps"><div><span>1</span><section><strong>${L('共用QRを読み取る','扫描共用二维码','Scan the shared QR')}</strong><p>${L('同じスポットのQRから、貸出登録・返却登録を選びます。','同一伞点二维码，选择借用登记或归还登记。','The same station QR opens both loan and return registration.')}</p></section></div><div><span>2</span><section><strong>${L('登録フォームに記入','填写登记表','Complete the form')}</strong><p>${L('貸出は学籍番号・名前・メールアドレス、返却は学籍番号・名前・傘の状態を記入します。','借用填写学号、姓名及邮箱；归还填写学号、姓名及雨伞状态。','For loans, enter your student ID, name and email. For returns, enter your student ID, name and umbrella condition.')}</p></section></div><div><span>3</span><section><strong>${L('登録完了を確認','确认登记完成','Check the confirmation')}</strong><p>${L('貸出登録完了後に傘を持ち出し、1週間以内に返却登録まで済ませてください。','借用登记成功后再取伞，并在一周内完成归还登记。','Take the umbrella after your loan is registered. Complete the return registration within one week.')}</p></section></div></div>${formNotice()}${btn(L('確認しました','我知道了','Got it'),'close-dialog','primary full')}`);}
function help(){rules();}
function borrowedPage(){const a=state.active;if(!a)return rentalPage();return `<section class="completion borrowed-complete"><div class="completion-check">${icon('check')}</div><p class="eyebrow">READY FOR THE RAIN.</p><h1>${L('貸出が完了しました。','借伞成功。')}</h1><p>${L('傘をお取りください。貸出期間は1週間です。','请取走雨伞，借用期限为一周。')}</p><div class="borrowed-ticket panel"><div><span>${L('貸出スポット','借用伞点')}</span><strong>${esc(name(spot(a.from)))}</strong></div><div><span>${L('傘番号','雨伞编号')}</span><strong>${esc(a.umbrella)}</strong></div><div><span>${L('認証方法','认证方式')}</span><strong>${methodName(a.borrowMethod)}</strong></div></div>${registrationRecord(a,'borrow')}${duePanel(a)}${policyBox()}<a href="#rental" class="btn primary full">${L('利用状況を見る','查看借用状态')}${icon('arrow')}</a></section>`;}
function verifiedMethod(id,mode){if(!verifiedAuth||verifiedAuth.id!==id||verifiedAuth.mode!==mode||Date.now()>verifiedAuth.expiresAt||(mode==='return'&&verifiedAuth.rentalId!==state.active?.id))throw Error('auth');return verifiedAuth.method;}
function returnCostMarkup(damaged=!!state.active?.damageReported){const a={...state.active,damageReported:damaged},cost=compensationFor(a);return `<div class="return-cost ${cost.amount?'has-fee':''}"><div><span>${L('基本利用料金','基础使用费')}</span><strong>¥0</strong></div><div><span>${L('弁償代（デモ）','赔偿金额（演示）')}</span><strong>¥${cost.amount.toLocaleString()}</strong></div><p>${cost.amount?cost.reasons.map(r=>r==='overdue'?L('期限超過','逾期未还'):L('破損','损坏')).join(' / ')+L('：1本につき2,000円。実際の請求・決済はありません。','：每把伞 2,000 日元，不产生真实账单或扣款。'):L('期限内・破損なしの通常利用は無料です。','期限内完好归还，正常使用免费。')}${a.policyVersion===1?L('旧版の利用には弁償代を適用しません。','旧版借用不追加赔偿金额。'):''}</p></div>`;}
function damageDialog(){const a=state.active;if(!a)return;openDialog(`<div class="dialog-icon warning">${icon('alert')}</div><p class="eyebrow">TAKE CARE OF THE NEXT PERSON.</p><h2 id="dialog-title">${L('傘の破損を申告','申报雨伞损坏')}</h2><p class="dialog-description">${esc(a.umbrella)} · ${L('壊れた傘は、再貸出しないように記録します。','损坏的雨伞会记录为待检修，避免再次借出。')}</p>${policyBox()}<form id="damage-form"><label>${L('破損の状況（任意）','损坏情况（选填）')}<textarea name="note" maxlength="1000" rows="3" placeholder="${L('例：傘の骨が折れている','例如：伞骨折断')}">${esc(a.damageNote||'')}</textarea></label><button class="btn primary full" type="submit">${L('破損を記録する（デモ）','记录损坏（演示）')}</button></form>${a.damageReported?btn(L('破損申告を取り消す','撤销损坏申报'),'clear-damage','ghost full'):''}<p class="form-caption">${L('このブラウザにのみ保存されます。まだ返却は完了していません。','仅保存在当前浏览器，此操作不会完成归还。')}</p>`);}

function formSteps(step){return `<div class="registration-steps" aria-label="${L('利用の流れ','操作流程','Steps')}">${[L('QR読取','扫描二维码','Scan QR'),L('登録フォーム','填写登记','Register'),L('完了','完成','Done')].map((n,i)=>`<span class="${i+1===step?'active':i+1<step?'done':''}"><b>${i+1<step?'✓':i+1}</b>${n}</span>`).join('')}</div>`;}
function formNotice(){return `<div class="form-demo-notice">${icon('shield')}<p>${L('Googleフォームの流れを再現したデモです。実際のGoogleフォームには送信されず、このブラウザに保存されます。','这是 Google 表单流程的演示。信息仅保存在当前浏览器，不会发送至真实 Google 表单。','This demo follows the Google Forms flow. Entries are saved in this browser, not sent to a live Google Form.')}</p></div>`;}
function stationPage(id){const s=SPOTS.find(s=>s.id===id);if(!s)return `<section class="panel empty-state"><h1>${L('スポットが見つかりません','未找到伞点','Station not found')}</h1><a class="btn primary" href="#spots">${L('スポットを探す','寻找伞点','Find a station')}</a></section>`;return `${pageHeading('ONE QR. BORROW OR RETURN.',esc(name(s)),L('このQRは貸出・返却の両方に使えます。','同一个二维码，可以借伞，也可以还伞。','Use this same QR code to borrow or return an umbrella.'))}<div class="station-landing panel"><img class="station-photo" src="./assets/umbrella-spot-v3.jpg" alt="${L('共用QRの案内と傘かご','共用二维码指示牌与伞篮','Shared QR sign and umbrella basket')}"><div class="station-landing-body"><span class="category-label">${icon('pin')}${esc(field(s,'detail'))}</span><h2>${L('どちらの登録をしますか？','请选择登记类型','What would you like to do?')}</h2><p class="station-stock">${L('貸出可能','可借雨伞','Available')} <strong>${state.inventory[id]}</strong> · ${L('返却枠','归还空位','Return spaces')} <strong>${returnSlots(state,id)}</strong></p><div class="station-actions">${btn(icon('umbrella')+L('貸出登録へ','填写借用登记','Register a loan'),'station-borrow','primary full',`data-id="${id}" ${state.active||state.inventory[id]===0?'disabled':''}`)}${btn(icon('check')+L('返却登録へ','填写归还登记','Register a return'),'station-return','secondary full',`data-id="${id}" ${!state.active||returnSlots(state,id)===0?'disabled':''}`)}</div>${state.active?`<p class="note">${L('利用中の傘','正在借用的伞','Your current umbrella')}：${esc(state.active.umbrella)} <a class="text-link" href="#rental">${L('利用状況を見る','查看借用状态','View loan')}</a></p>`:`<p class="note">${L('返却登録は、貸出登録したブラウザで行ってください。','请使用完成借用登记的同一浏览器归还。','To return an umbrella in this demo, use the browser where you registered the loan.')}</p>`}${policyBox()}</div></div>${formNotice()}`;}
function qrPage(){const s=spot(qrSelected),url=stationUrl(s.id,currentOrigin());return `${pageHeading('A SMALL CODE. A SHARED UMBRELLA.',L('スポットのQRコード','伞点二维码','Station QR codes'),L('貸出・返却共用。印刷してスポットに掲示できます。','借还共用，可下载并打印在伞点展示。','One code for borrowing and returns. Download it for a station sign.'))}<div class="qr-layout"><section class="panel qr-preview"><p class="eyebrow">RAIN FLOW AS · 3.0</p><h2>${esc(name(s))}</h2><div class="qr-code-image">${qrSvg(url)}</div><strong>${L('貸出・返却はこちら','扫码借伞 / 还伞','SCAN TO BORROW / RETURN')}</strong><p>${L('スマホのカメラで読み取れます','用手机相机扫描即可进入','Scan with your phone camera')}</p><span class="qr-station-code">${s.code}</span><div class="qr-downloads">${btn(icon('download')+L('PNGを保存','下载 PNG','Download PNG'),'qr-download','primary',`data-id="${s.id}" data-value="png"`)}${btn('SVG','qr-download','secondary',`data-id="${s.id}" data-value="svg"`)}</div></section><section><div class="panel qr-options"><h2>${L('スポットを選ぶ','选择伞点','Choose a station')}</h2><div class="qr-spot-selector">${SPOTS.map(p=>`<button class="${p.id===s.id?'active':''}" data-action="qr-select" data-id="${p.id}" aria-pressed="${p.id===s.id}">${icon(p.type)}<span>${esc(name(p))}</span>${icon(p.id===s.id?'check':'chevron')}</button>`).join('')}</div><label class="qr-url-label">${L('QRコードのリンク先','二维码目标链接','QR destination')}<input id="qr-link" readonly value="${esc(url)}"></label><div class="qr-link-actions">${btn(L('リンクをコピー','复制链接','Copy link'),'qr-copy','secondary small')}<a class="text-link" href="${esc(url)}">${L('開いて確認','打开查看','Open station')}${icon('arrow')}</a></div></div><div class="qr-instructions">${formSteps(1)}<p>${L('1. QRを読む  2. 貸出・返却を選ぶ  3. 登録フォームを送信','1. 扫描二维码　2. 选择借用或归还　3. 提交登记表','1. Scan the code  2. Choose borrow or return  3. Submit the registration')}</p></div><div class="info-box"><strong>${L('独自ドメインについて','关于独立域名','Using your own domain')}</strong><p>${L('現在のサイトURLを使用しています。独自ドメインの設定後、そのドメインでこの画面を開くと、新しいURLのQRを保存できます。','当前使用现有站点网址。绑定独立域名后，用新域名打开此页面即可生成新网址的二维码。','These codes use the current site address. After connecting your own domain, open this page on that domain to download updated codes.')}</p></div></section></div>`;}
function registrationRecord(r,kind){const f=kind==='borrow'?r.borrowRegistration:r.returnRegistration;if(!f)return '';return `<div class="registration-record"><strong>${kind==='borrow'?L('貸出登録を保存しました','借用登记已保存','Loan registration saved'):L('返却登録を保存しました','归还登记已保存','Return registration saved')}</strong><dl><div><dt>${L('学籍番号','学号','Student ID')}</dt><dd>${esc(f.studentId)}</dd></div><div><dt>${L('名前','姓名','Name')}</dt><dd>${esc(f.name)}</dd></div><div><dt>${L('登録日','登记日期','Registration date')}</dt><dd>${esc(f.date)}</dd></div></dl><small>${L('このブラウザに保存されたデモ登録です。','这是保存在当前浏览器中的演示登记。','This is a demo record stored in this browser.')}</small></div>`;}

function shell(content,page){
 const nav=[['home','home',L('ホーム','首页')],['spots','pin',L('傘スポット','附近伞点')],['rental','umbrella',L('利用中の傘','我的借用')],['services','gift',L('クーポン・サービス','优惠与服务')],['profile','user',L('マイページ','个人中心')],['qr','qr',L('QRコード','二维码','QR codes')]];
 const active=page==='borrow'?'spots':['return','complete','borrowed'].includes(page)?'rental':page;
 return `<aside class="sidebar"><a class="brand" href="#home" aria-label="Rain Flow As">${icon('umbrella')}<span>Rain Flow As<small>${state.lang==='en'?'COMMUNITY UMBRELLA SHARING':'レインフロー・アズ'}</small></span></a><div class="nav-label">${L('雨の日のおとも','陪伴每个雨天')}</div><nav aria-label="${L('メインメニュー','主菜单')}">${nav.map(([id,i,t])=>`<a href="#${id}" class="nav-item ${active===id?'selected':''}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${id==='rental'&&state.active?'<span class="nav-dot"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="little-mission">${icon('leaf')}<p>${L('1本の傘から、<br>やさしい街へ。','从一把伞开始，<br>让城市多一点温暖。')}</p><span>SHARE AN UMBRELLA.</span></div><a href="#advertiser" class="nav-item advertiser-link ${page==='advertiser'?'selected':''}">${icon('chart')}<span>${L('広告主の方へ','广告主后台')}</span>${icon('chevron')}</a><button class="nav-item" data-action="help">${icon('help')}<span>${L('ご利用ガイド','使用指南')}</span></button><p class="sidebar-footer">© 2026 Rain Flow As</p></div></aside>
 <div class="main-shell"><header class="topbar"><a class="mobile-brand" href="#home">${icon('umbrella')}<strong>Rain Flow As</strong></a><div class="breadcrumb">${L('傘をシェアして、街とつながる。','共享一把伞，连接一座城。')}</div><div class="header-actions"><span class="prototype-tag">${L('体験版 3.0','体验版 3.0','Demo 3.0')}</span><div class="language-switcher" role="group" aria-label="Language">${[['ja','JP','日本語'],['zh','中文','中文'],['en','EN','English']].map(([code,label,full])=>`<button data-action="language" data-value="${code}" class="${state.lang===code?'current':''}" aria-label="${full}" aria-pressed="${state.lang===code}">${label}</button>`).join('')}</div><button class="icon-btn help-top" data-action="help" aria-label="${L('使い方','使用帮助')}">${icon('help')}</button><a href="#profile" class="avatar" aria-label="${L('マイページ','个人中心')}">${avatar()}</a></div></header><main id="main-content" tabindex="-1">${content}</main><footer class="page-footer"><span>RAIN FLOW AS</span><p>${L('体験版：天気・スポット・在庫・広告はサンプルです。実際の貸出は行いません。','体验版：天气、伞点、库存及广告均为示例，不会产生真实借还操作。')}</p></footer></div>
 <nav class="mobile-nav" aria-label="${L('モバイルメニュー','手机导航')}">${nav.filter(n=>!['services','qr'].includes(n[0])).map(([id,i,t])=>`<a href="#${id}" class="${active===id?'selected':''}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${id==='rental'?L('利用中','借用中'):id==='spots'?L('スポット','伞点'):t}</span>${id==='rental'&&state.active?'<b></b>':''}</a>`).join('')}</nav>`;
}
function pageHeading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="page-subtitle">${sub}</p></div>${action}</div>`;}
function spotRow(s,mode='borrow'){
 const stock=state.inventory[s.id],available=mode==='return'?returnSlots(state,s.id):stock,isFav=state.favorites.includes(s.id);
 return `<article class="spot-row"><div class="spot-type ${s.type}">${icon(s.type)}</div><div class="spot-copy"><button class="spot-name" data-action="${mode==='return'?'choose-return':'detail'}" data-id="${s.id}">${esc(name(s))}</button><div class="spot-meta"><span class="stock ${available===0?'empty':available<=3?'low':''}"><i></i>${mode==='return'?L(`返却枠 ${available}本`,`可还 ${available} 把`,`${available} return spaces`):L(`残り ${stock}本`,`可借 ${stock} 把`,`${stock} available`)}</span><span class="meta-dot">·</span><span>${distance(s)}</span><span class="walk-distance">${L(`徒歩${s.walk}分`,`步行${s.walk}分钟`,`${s.walk} min walk`)}${geo?' *':''}</span></div></div><button class="icon-btn favorite ${isFav?'saved':''}" data-action="favorite" data-id="${s.id}" aria-pressed="${isFav}" aria-label="${esc(name(s))} ${isFav?L('お気に入り解除','取消收藏'):L('お気に入り登録','收藏')}">${icon('heart')}</button><button class="row-go" data-action="${mode==='return'?'choose-return':'detail'}" data-id="${s.id}" ${available===0?'disabled':''} aria-label="${esc(name(s))} ${L('詳細','详情')}">${icon('chevron')}</button></article>`;
}
function mapPanel(big=false){const returning=route().page==='return';const visible=big?filteredSpots(returning?'return':'borrow'):nearby().slice(0,3);if(big&&visible.length&&!visible.some(s=>s.id===selectedMap))selectedMap=visible[0].id;return `<div class="map-panel ${big?'large-map':''}"><svg class="map-base" viewBox="0 0 600 380" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="600" height="380" fill="#f0f3f6"/><g fill="#e0e7ed"><rect x="26" y="27" width="91" height="67" rx="8"/><rect x="151" y="30" width="91" height="39" rx="6"/><rect x="149" y="92" width="71" height="68" rx="6"/><rect x="253" y="32" width="132" height="62" rx="8"/><rect x="441" y="131" width="127" height="54" rx="6"/><rect x="335" y="209" width="67" height="111" rx="7"/><rect x="25" y="218" width="58" height="125" rx="7"/><rect x="137" y="255" width="123" height="82" rx="8"/><rect x="285" y="133" width="99" height="38" rx="6"/><rect x="441" y="262" width="121" height="80" rx="6"/></g><path d="M0 193 600 211M112 0 102 380M410 0 421 380M0 116 600 106M271 0 280 380" fill="none" stroke="#fff" stroke-width="18"/><path d="m0 321 600-267" stroke="#fff" stroke-width="25"/><path d="m0 321 600-267" stroke="#d4dce5" stroke-width="2" stroke-dasharray="7 6"/><rect x="453" y="10" width="133" height="80" rx="20" fill="#d4e6dd"/><rect x="171" y="190" width="79" height="44" rx="14" fill="#d4e6dd"/><path d="M468 46h104m-93-20 70 48" stroke="#bfd7cc" stroke-width="3"/></svg><div class="map-label campus">${L('国士舘大学','国士馆大学')}</div><div class="map-label station">${L('梅ヶ丘','梅丘')}</div><div class="map-label park">${L('羽根木公園','羽根木公园')}</div><span class="map-current" style="left:51%;top:66%"><i></i><span>${L('現在地（例）','当前位置（示例）')}</span></span>${visible.map(s=>`<button class="map-pin ${selectedMap===s.id?'active':''}" style="left:${s.x}%;top:${s.y}%" data-action="map-select" data-id="${s.id}" aria-label="${esc(name(s))}">${icon('umbrella')}<b>${returning?returnSlots(state,s.id):state.inventory[s.id]}</b></button>`).join('')}<span class="map-caption">${L('スポット案内図 · 実際の地図ではありません','伞点示意图 · 非真实地图')}</span><button class="map-expand icon-btn" data-action="${big?'locate':'map-open'}" aria-label="${L('スポットを見る','查看伞点')}">${icon(big?'locate':'map')}</button>${big&&visible.length?`<div class="map-selection"><span>${esc(name(spot(selectedMap)))}</span>${btn((returning?L('ここに返す','归还到这里'):L('詳細を見る','查看详情'))+icon('arrow'),returning?'choose-return':'detail','primary small',`data-id="${selectedMap}" ${returning&&returnSlots(state,selectedMap)<1?'disabled':''}`)}</div>`:''}</div>`;}
function home(){const s=nearby().slice(0,3);return `${pageHeading('A LITTLE RAIN, A LITTLE KINDNESS.',L('雨の日も、<span>軽やかに。</span>','下雨天，也能<span>轻松出发。</span>'),L('必要なときに借りて、好きなスポットへ。','需要时借一把，顺路就能归还。'),`<div class="location-pill">${icon('pin')}<span>${L('世田谷・国士舘大学周辺','世田谷 · 国士馆大学周边')}</span></div>`)}
 ${state.active?`<div class="active-banner">${icon('umbrella')}<div><strong>${L('傘をご利用中です','你有一把正在使用的伞')} <span>${esc(state.active.umbrella)}</span></strong><small>${esc(name(spot(state.active.from)))} · ${L('返却期限','归还期限')} ${stamp(deadline(state.active))}</small></div><a href="#rental">${L('利用状況を見る','查看借用')}${icon('arrow')}</a></div>`:''}
 <div class="hero-grid"><section class="weather-card"><div class="weather-top"><span>${icon('pin')}${L('世田谷区','世田谷区')}</span>${labelDemo()}</div><div class="weather-copy"><p>${L('空模様を気にせず、出かけよう。','别让天气，打乱你的计划。')}</p><div class="temperature">22<span>°</span><div>${L('雨、ときどきくもり','小雨转多云')}<small>${L('降水確率','降水概率')} <b>80%</b></small></div></div><div class="weather-tip">${icon('rain')}<span>${L('帰り道にも、傘がある安心を。','回家的路上，也有一把伞等你。')}</span></div></div>${umbrellaArt()}<div class="weather-bottom"><span>${L('気持ちまで、晴れやかに。','让心情，也放个晴。')}</span><span>RAIN OR SHINE.</span></div></section>
 <section class="quick-card"><div class="quick-top"><span>UMBRELLA SHARING</span>${icon('umbrella')}</div><h2>${L('その雨に、<br>シェアする選択を。','这一场雨，<br>让我们共享一把伞。')}</h2><div class="free-price"><span>${L('利用料金','借用费用')}</span><strong>¥0</strong><span>${L('1週間以内','一周内使用')}</span></div>${btn(icon(state.active?'pin':'qr')+(state.active?L('返却スポットを探す','寻找归还点'):L('傘を借りる','借一把伞')),state.active?'return-list':'borrow-near','light')}<p>${icon('shield')}${L('地域のスポンサーが支えています','由社区赞助商提供支持')}</p></section></div>${policyStrip()}
 <section class="nearby-section"><div class="section-heading"><div><h2>${L('近くの傘スポット','附近的伞点')} <span class="count-badge">3</span></h2><p>${L('あなたの街で、すぐに見つかる。','一把好借、好还的伞，就在你身边。')}</p></div><a class="text-link" href="#spots">${L('すべて見る','查看全部')}${icon('arrow')}</a></div><div class="nearby-layout">${mapPanel()}<div class="nearby-list">${s.map(i=>spotRow(i)).join('')}<div class="list-footnote">${icon('clock')}${L('距離・徒歩時間は参考値です','距离及步行时间为示例参考值')}</div></div></div></section>
 <section class="how-strip"><div class="how-intro">${icon('leaf')}<strong>${L('借りる。歩く。つなぐ。','借一把，走一程，传一份温暖。')}</strong></div><div><span>01</span>${L('近くで見つける','找到附近伞点')}</div>${icon('chevron')}<div><span>02</span>${L('QRで登録する','扫码填写登记','Scan & register')}</div>${icon('chevron')}<div><span>03</span>${L('1週間以内に返す','一周内归还')}</div></section>`;}
function filteredSpots(mode){return nearby().filter(s=>(!query||(s.name+s.zh+s.en+s.area+s.areaZh+s.areaEn).toLowerCase().includes(query.toLowerCase()))&&(filter!=='favorite'||state.favorites.includes(s.id))&&(filter!=='available'||(mode==='return'?returnSlots(state,s.id)>0:state.inventory[s.id]>0)));}
function spotsPage(mode='borrow'){const returning=mode==='return';return `${pageHeading(returning?'RETURN YOUR UMBRELLA.':'FIND YOUR NEXT UMBRELLA.',returning?L('返却スポットを探す','寻找归还伞点'):L('傘スポット','附近伞点'),returning?L('借りた場所と違うスポットにも返せます。','可归还到任意有空位的伞点，无需原路返回。'):L('お気に入りのスポットを、あなたの街に。','在你的城市，找到顺路的那把伞。'),btn(icon('locate')+L('現在地を取得','获取当前位置'),'locate','secondary'))}${returning?`<div class="notice">${icon('umbrella')}${L('傘をスポットに戻し、貸出・返却共用のQRから返却フォームを入力してください。','将雨伞放回伞点，扫描借还共用二维码，填写归还登记表。','Put the umbrella back and scan the shared QR code to complete the return form.')}</div>`:''}
 <div class="spot-toolbar"><label class="search-box">${icon('search')}<input id="spot-search" type="search" placeholder="${L('駅名・スポット名で検索','搜索车站或伞点名称')}" value="${esc(query)}" aria-label="${L('スポット検索','搜索伞点')}"></label><div class="view-toggle"><button class="${view==='list'?'active':''}" data-action="view" data-value="list">${L('リスト','列表')}</button><button class="${view==='map'?'active':''}" data-action="view" data-value="map">${icon('map')}${L('マップ','地图')}</button></div></div><div class="filter-row">${[['all',L('すべて','全部')],['available',returning?L('返却可能','可以归还'):L('貸出可能','可以借用')],['favorite',L('お気に入り','我的收藏')]].map(([id,t])=>`<button class="filter-chip ${filter===id?'active':''}" data-action="filter" data-value="${id}" aria-pressed="${filter===id}">${id==='favorite'?icon('heart'):''}${t}</button>`).join('')}<span class="filter-note">${geo?L('GPS位置から概算（徒歩時間は例）','按 GPS 位置估算（步行时间为示例）'):L('世田谷周辺・参考距離順','世田谷周边 · 按示例距离排序')}</span></div>${view==='map'?`<div id="spot-map">${mapPanel(true)}</div>`:''}<section class="spots-results panel" id="spots-results">${spotResults(mode)}</section><p class="muted note">${L('スポット・在庫・座標はデモです。GPSは距離計算のみに使用し、保存しません。営業時間は表示例で、貸出可否には連動しません。','伞点、库存及坐标为演示数据。GPS 仅用于估算距离，不会保存。营业时间为示例，未关联借还限制。')}</p>`;}
function spotResults(mode){const s=filteredSpots(mode);return s.length?s.map(s=>spotRow(s,mode)).join(''):`<div class="empty-state">${icon('search')}<h3>${L('スポットが見つかりません','没有找到伞点')}</h3><p>${L('検索条件を変えるか、ほかのスポットを探してください。','请更换关键词或筛选条件。')}</p>${btn(L('条件をリセット','重置搜索'),'clear-filters','secondary')}</div>`;}

function sponsorCards(){return `<div class="sponsor-cards"><button class="sponsor-card coffee-sponsor" data-action="offer" data-id="coffee"><div class="sponsor-art">${icon('coffee')}<span>COFFEE<br>& A LITTLE BREAK.</span></div><div><span class="sponsor-kicker">${L('地域のカフェ · 広告（例）','社区咖啡店 · 示例广告')}</span><strong>${L('雨の日は、ほっとひと息。','雨天，喝杯咖啡再出发。')}</strong><p>${L('ドリンク 50円OFF','饮品立减 50 日元')}${icon('arrow')}</p></div></button><button class="sponsor-card green-sponsor" data-action="offer" data-id="shop"><div class="sponsor-art">${icon('gift')}<span>GOOD THINGS<br>IN YOUR TOWN.</span></div><div><span class="sponsor-kicker">${L('まちのお店 · 広告（例）','街角小店 · 示例广告')}</span><strong>${L('いつもの街に、いい出会い。','在熟悉的街角，发现小惊喜。')}</strong><p>${L('お買いもの 10%OFF','购物享九折')}${icon('arrow')}</p></div></button></div>`;}
function borrowPage(id){const s=spot(id),n=state.inventory[s.id];return `<button class="back-link" data-action="back-spots">${icon('back')}${L('スポット一覧に戻る','返回伞点列表')}</button>${pageHeading('READY WHEN YOU ARE.',L('傘を借りる','借一把伞'),L('ここから、いつもの一日を。','从这里出发，继续今天的旅程。'))}<div class="detail-grid"><section class="panel spot-detail"><div class="station-picture"><img class="station-photo" src="./assets/umbrella-spot-v3.jpg" alt="${L('3.0資料の、共用QR付き看板と傘かご','3.0 文件中的共用二维码指示牌与伞篮','Shared QR sign and umbrella basket from the version 3.0 reference')}"><span>${L('3.0資料の設置例','3.0 文件中的伞点示例','Station example from the 3.0 brief')}</span></div><div class="spot-detail-body"><div class="section-heading"><span class="category-label">${icon(s.type)}${field(s,'area')}</span><button class="icon-btn favorite ${state.favorites.includes(s.id)?'saved':''}" data-action="favorite" data-id="${s.id}" aria-label="${L('お気に入り切り替え','切换收藏')}" aria-pressed="${state.favorites.includes(s.id)}">${icon('heart')}</button></div><h2>${esc(name(s))}</h2><p>${icon('pin')}${esc(field(s,'detail'))}</p><div class="detail-stats"><div><span>${L('貸出可能','可借雨伞')}</span><strong>${n}<small>${L('本','把')}</small></strong></div><div><span>${L('現在地から（例）','距离（示例）')}</span><strong>${distance(s)}</strong></div><div><span>${L('利用時間（例）','营业时间（示例）')}</span><strong class="hours">${s.hours==='24時間'?L('24時間','24 小时'):s.hours}</strong></div></div></div></section><div><section class="panel borrowing-card"><span class="eyebrow">FREE UMBRELLA SHARING</span><h2>${L('気軽に借りて、<br>気持ちよく返そう。','轻松借用，<br>顺路归还。')}</h2><div class="borrow-price"><span>${L('利用料金','借用费用')}</span><strong>¥0</strong><span>${L('無料','免费')}</span></div><ul class="check-list"><li>${icon('check')}${L('すべてのスポットで返却OK','可在任意有空位的伞点归还')}</li><li>${icon('check')}${L('貸出期間は1週間（7日間）','借用期限为一周（7 天）')}</li><li>${icon('check')}${L('QRを読み取り、貸出登録してから利用','扫码并完成借用登记后即可取伞','Scan the QR and register before taking an umbrella')}</li></ul>${policyBox()}${state.active?`<a href="#rental" class="btn primary full">${L('利用中の傘を確認','查看正在借用的伞')}${icon('arrow')}</a>`:btn(icon('qr')+L('QRコードで借りる','扫码借伞','Scan to borrow'),'auth-borrow','primary full',`data-id="${s.id}" ${n===0?'disabled':''}`)}<p class="form-caption">${L('Googleフォームの登録を想定した体験版です。データはこのブラウザに保存します。','按 Google 表单登记流程演示，数据保存在当前浏览器。','A demo of the Google Forms registration flow. Records stay in this browser.')}</p></section><div class="support-note">${icon('shield')}<div><strong>${L('地域とつながる、無料の傘','社区支持，让每一把伞免费共享')}</strong><p>${L('広告スポンサーの協力で、雨の日の移動をサポート。','广告赞助商的支持，让雨天的出行更轻松。')}</p></div></div></div></div><section class="sponsor-section"><div class="section-heading"><h2>${L('雨の日に、うれしい寄り道','雨天，也有值得停留的地方')}</h2><span class="muted">${L('スポンサー · サンプル','赞助商 · 示例')}</span></div>${sponsorCards()}</section>`;}

function rentalPage(){if(!state.active)return `${pageHeading('YOUR UMBRELLA, YOUR PACE.',L('利用中の傘','我的借用'),L('雨の日の移動を、もっと気軽に。','雨天出行，多一份轻松。'))}<section class="panel empty-state generous">${icon('umbrella')}<h2>${L('今は、傘を利用していません','目前没有借用中的雨伞')}</h2><p>${L('近くのスポットで、あなたを待つ傘を探しましょう。','去附近的伞点，找一把等你出发的伞吧。')}</p><a href="#spots" class="btn primary">${L('傘スポットを探す','寻找伞点')}${icon('arrow')}</a></section>`;
const a=state.active,s=spot(a.from),cost=compensationFor(a);return `${pageHeading('ENJOY YOUR WALK.',L('この傘と、もう少し。','和这把伞，再走一程。'),L('貸出期間は1週間。返却期限を確認しておきましょう。','借用期限为一周，记得按时归还。'),`<span class="status-pill ${cost.overdue?'overdue-pill':''}">${cost.overdue?L('期限超過','已逾期'):L('利用中','使用中')}</span>`)}<div class="rental-grid"><section><div class="active-rental-card"><div class="rental-card-top"><span>YOUR UMBRELLA</span><span>${L('基本利用料 ¥0','基础使用费 ¥0')}</span></div>${umbrellaArt()}<div class="rental-number"><span>${L('傘番号','雨伞编号')}</span><strong>${esc(a.umbrella)}</strong></div><div class="rental-live"><div><span>${L('利用時間','已使用')}</span><strong data-live-duration>${duration(a.startedAt,rentalNow(a))}</strong></div><div><span>${L('弁償代（デモ）','赔偿金额（演示）')}</span><strong data-live-fee>¥${cost.amount.toLocaleString()}</strong></div></div><dl class="rental-info"><div><dt>${L('利用開始','借用开始')}</dt><dd>${stamp(a.startedAt)}</dd></div><div><dt>${L('貸出スポット','借用伞点')}</dt><dd>${esc(name(s))}</dd></div><div><dt>${L('認証方法','认证方式')}</dt><dd>${methodName(a.borrowMethod)}</dd></div></dl></div><div id="rental-due">${duePanel(a)}</div></section><section><div class="section-heading"><div><h2>${L('近くの返却スポット','附近可归还伞点')}</h2><p>${L('傘を戻し、QRから返却登録を完了。','放回雨伞，扫码填写归还登记。','Put the umbrella back, then scan to register its return.')}</p></div></div><div class="panel return-list">${nearby(SPOTS.filter(s=>returnSlots(state,s.id)>0)).slice(0,3).map(s=>spotRow(s,'return')).join('')}</div>${btn(icon('qr')+L('返却スポットを選ぶ','选择归还伞点'),'return-list','primary full return-cta')}<div class="damage-action ${a.damageReported?'reported':''}">${icon('alert')}<div><strong>${a.damageReported?L('破損の申告を記録しました','已记录损坏申报'):L('傘が壊れてしまったら','如果雨伞损坏了')}</strong><p>${a.damageReported?L('返却時に検修用として管理します。','归还后将列为待检修，不会再次借出。'):L('返却前に、破損の状況をお知らせください。','请在归还前记录损坏情况。')}</p></div><button class="text-link" data-action="damage">${a.damageReported?L('編集','编辑'):L('申告','申报')}${icon('chevron')}</button></div>${policyBox()}<div class="care-note">${icon('leaf')}<div><strong>${L('次の人にも、やさしさを。','把这份温暖，留给下一位。')}</strong><p>${L('返却前に水気を切って、傘をたたんでください。','归还前，请轻轻甩去水滴，将雨伞收好。')}</p></div></div><details class="demo-scenarios"><summary>${L('3.0の動作を試す','体验 3.0 情景','Try a 3.0 scenario')}</summary><p>${L('この借用だけのデモ時刻を切り替え、期限超過時の表示を確認できます。端末の時刻は変更しません。','仅切换本次借用的演示时钟，查看逾期状态，不修改设备时间。')}</p>${btn(a.demoOverdue?L('現在の時刻に戻す','恢复当前时间'):L('期限超過1時間を再現','模拟逾期 1 小时'),'overdue-demo','secondary small')}</details></section></div>`;}
function completePage(id){const h=state.history.find(r=>r.id===id)||state.history[0];if(!h)return rentalPage();return `<section class="completion"><div class="completion-check">${icon('check')}</div><p class="eyebrow">THANK YOU FOR SHARING.</p><h1>${L('また、次の雨の日に。','下一个雨天，我们再见。')}</h1><p>${L('返却が完了しました。ご利用ありがとうございました。','归还成功，感谢你参与共享。')}</p><div class="panel receipt"><div class="receipt-title"><strong>${L('今回のご利用','本次借用')}</strong><span>${esc(h.umbrella)}</span></div><div class="receipt-summary"><div><span>${L('利用時間','使用时长')}</span><strong>${duration(h.startedAt,h.endedAt)}</strong></div><div><span>${L('基本利用料金','基础使用费')}</span><strong>¥0<small>${L('無料','免费')}</small></strong></div></div><div class="receipt-compensation ${h.compensation?'has-fee':''}"><span>${L('弁償代（デモ）','赔偿金额（演示）')}</span><strong>¥${(h.compensation||0).toLocaleString()}</strong>${h.compensation?`<p>${(h.compensationReasons||[]).map(r=>r==='overdue'?L('期限超過','逾期未还'):L('破損','损坏')).join(' / ')} · ${L('未精算・実際の請求はありません','未结算 · 不会产生真实账单')}</p>`:''}</div>${h.damageReported?`<p class="quarantine-note">${L('破損した傘は検修用として記録し、貸出在庫には戻していません。','损坏雨伞已列为待检修，不会计入可借库存。')}</p>`:''}${h.demoOverdue?`<p class="quarantine-note">${L('期限超過のデモ時刻で返却した記録です。','此记录使用了逾期情景的演示时钟。')}</p>`:''}<dl><div><dt>${L('返却期限','归还期限')}</dt><dd>${h.dueAt?stamp(h.dueAt):L('旧版の利用','旧版借用')}</dd></div><div><dt>${L('認証方法','认证方式')}</dt><dd>${methodName(h.borrowMethod)} / ${methodName(h.returnMethod)}</dd></div><div><dt>${L('貸出','借出')}</dt><dd>${esc(name(spot(h.from)))}<small>${stamp(h.startedAt)}</small></dd></div><div><dt>${L('返却','归还')}</dt><dd>${esc(name(spot(h.to)))}<small>${stamp(h.endedAt)}</small></dd></div></dl></div>${registrationRecord(h,'return')}<div class="rating-box"><h3>${L('使い心地はいかがでしたか？','这次体验怎么样？')}</h3><p>${L('あなたの声が、もっとやさしいサービスに。','你的反馈，让每个雨天更美好。')}</p><form id="rating-form" data-id="${esc(h.id)}"><div class="stars" role="group" aria-label="${L('5段階評価','五星评价')}">${[1,2,3,4,5].map(i=>`<button type="button" class="star ${i<=(h.rating||rating)?'filled':''}" data-action="rate" data-value="${i}" aria-label="${i}${L('つ星','星')}" aria-pressed="${i===(h.rating||rating)}">${icon('star')}</button>`).join('')}</div><textarea name="feedback" maxlength="1000" placeholder="${L('ご感想や改善のアイデア（任意）','写下感受或改进建议（选填）')}" aria-label="${L('ご意見','反馈')}">${esc(h.feedback||'')}</textarea><button class="btn primary full" type="submit">${h.rating?L('評価を更新する','更新评价'):L('評価を保存する','保存评价')}${icon('arrow')}</button><p class="form-caption">${L('体験版の評価は、このブラウザに保存されます。','体验版评价仅保存在当前浏览器。')}</p></form></div><a class="text-link" href="#home">${L('ホームに戻る','返回首页')}${icon('arrow')}</a></section>`;}

function profilePage(){return `${pageHeading('A LITTLE MORE YOU.',L('マイページ','个人中心'),L('あなたの傘の記録を、ここに。','每一次借用，都留在这里。'),btn(icon('settings')+L('プロフィール編集','编辑资料'),'edit-profile','secondary'))}<div class="profile-header panel"><div class="profile-avatar">${avatar()}</div><div class="profile-intro"><h2>${esc(state.profile.name||L('ゲストさん','访客'))}</h2><p>${state.profile.name?'ID : RF-DEMO-001':L('ログインせずに体験できます','无需登录即可体验')}</p><span class="demo-label">${L('ローカルのデモプロフィール','本地演示资料')}</span></div>${btn(state.profile.name?L('デモログアウト','退出演示账号'):L('ログイン / 新規登録','登录 / 注册'),state.profile.name?'logout':'login','secondary')}</div><div class="profile-stats"><div class="panel"><span>${icon('umbrella')}${L('利用回数','借用次数')}</span><strong>${state.history.length}<small>${L('回','次')}</small></strong></div><div class="panel"><span>${icon('leaf')}${L('基本利用料金の合計','累计基础使用费')}</span><strong>¥0</strong><small class="compensation-total">${L('弁償代（デモ）','赔偿金额（演示）')} ¥${state.history.reduce((sum,h)=>sum+(h.compensation||0),0).toLocaleString()}</small></div><div class="panel"><span>${icon('heart')}${L('お気に入り','收藏伞点')}</span><strong>${state.favorites.length}<small>/ 2</small></strong></div></div><div class="profile-columns"><section><div class="section-heading"><h2>${L('お気に入りスポット','收藏伞点')}<span class="count-badge">${state.favorites.length}/2</span></h2></div><div class="panel">${state.favorites.length?state.favorites.map(id=>spotRow(spot(id))).join(''):`<div class="empty-state compact">${icon('heart')}<h3>${L('よく使うスポットを、ここに。','把常用伞点，收藏在这里。')}</h3><p>${L('ハートを押して、最大2つまで登録できます。','点击爱心，最多收藏两个伞点。')}</p><a class="text-link" href="#spots">${L('スポットを探す','寻找伞点')}${icon('arrow')}</a></div>`}</div></section><section><div class="section-heading"><h2>${L('利用履歴','借用记录')}</h2></div><div class="panel history-list">${state.history.length?state.history.map(h=>`<button class="history-row" data-action="history" data-id="${esc(h.id)}"><div class="history-icon">${icon('umbrella')}</div><div><strong>${esc(name(spot(h.from)))}</strong><small>${stamp(h.startedAt)} · ${duration(h.startedAt,h.endedAt)}</small></div><span>${h.compensation?`¥${h.compensation.toLocaleString()}<small>${L('弁償代・デモ','赔偿 · 演示')}</small>`:'¥0'}</span>${icon('chevron')}</button>`).join(''):`<div class="empty-state compact">${icon('clock')}<h3>${L('はじめての1本を借りてみよう','从借用第一把伞开始')}</h3><p>${L('返却すると、利用履歴に記録されます。','归还后，借用记录会显示在这里。')}</p></div>`}</div></section></div><div class="profile-bottom"><a href="#qr">${icon('qr')}${L('スポットのQRを表示・保存','查看及下载伞点二维码','View and download station QR codes')}${icon('chevron')}</a><a href="#services">${icon('gift')}${L('クーポン・サービス','优惠与服务')}${icon('chevron')}</a><button data-action="help">${icon('help')}${L('使い方・よくある質問','使用指南与常见问题')}${icon('chevron')}</button><a href="#advertiser">${icon('chart')}${L('広告主専用ページ','广告主后台')}${icon('chevron')}</a><button data-action="reset-prompt">${icon('settings')}${L('デモデータをリセット','重置演示数据')}${icon('chevron')}</button></div>`;}
function servicesPage(){return `${pageHeading('GOOD THINGS, AROUND YOU.',L('雨の日の、ちょっとうれしい。','给雨天，加一点小惊喜。'),L('傘シェアを支える、まちのスポンサーから。','来自支持共享雨伞的社区赞助商。'))}<div class="notice">${icon('gift')}${L('クーポンは体験用です。実際の店舗では利用できません。','优惠券仅供体验，无法在真实门店使用。')}</div>${sponsorCards()}<section class="saved-coupons"><div class="section-heading"><h2>${L('保存したクーポン','已领取的优惠券')}</h2></div><div class="panel">${state.coupons.length?state.coupons.map(c=>`<div class="coupon-row"><div class="coupon-symbol">${icon(c.id==='coffee'?'coffee':'gift')}</div><div><strong>${c.id==='coffee'?L('ドリンク 50円OFF','饮品立减 50 日元'):L('お買いもの 10%OFF','购物享九折')}</strong><small>${L('デモ限定 · 実店舗では利用不可','仅限演示 · 无法在门店使用')}</small></div>${btn(c.used?L('使用済み（デモ）','已使用（演示）'):L('使ってみる','模拟使用'),'use-coupon','secondary small',`data-id="${c.id}" ${c.used?'disabled':''}`)}</div>`).join(''):`<div class="empty-state compact">${icon('gift')}<h3>${L('気になるクーポンを見つけよう','领取一份雨天的小惊喜')}</h3><p>${L('上のスポンサーから、クーポンを保存できます。','点击上方赞助商卡片，即可领取优惠券。')}</p></div>`}</div></section><div class="care-note">${icon('leaf')}<div><strong>${L('広告が、無料の傘を支える。','广告支持，让共享雨伞保持免费。')}</strong><p>${L('スポンサーとのつながりを、日々のお得に。ポイント・歩数連動・決済機能は構想段階です。','让社区的支持，成为日常的小优惠。积分、步数联动及支付功能仍处于构想阶段。')}</p></div></div>`;}

function advertiserPage(){const areas=[L('大学周辺','大学周边'),L('駅周辺','车站周边'),L('商業施設','商业设施')];return `${pageHeading('RAIN FLOW AS FOR BUSINESS.',L('広告主ダッシュボード','广告主后台'),L('街を歩く傘が、あなたのブランドを届ける。','让行走在城市中的雨伞，传递你的品牌。'),btn(icon('plus')+L('広告掲載を申請','申请广告投放'),'ad-application','primary'))}<div class="notice">${icon('chart')}${L('デモ用の管理画面です。集計値・キャンペーンはサンプルで、申請はブラウザ内にのみ保存されます。','此为演示后台。统计与活动均为示例，申请仅保存在当前浏览器。')}</div><div class="ad-stats"><div class="panel stat-card"><span>${L('推定広告閲覧数','预计广告浏览量')}${icon('chart')}</span><strong>45,800<small>${L('人','人')}</small></strong><p><b>+12.5%</b> ${L('前月比（サンプル）','较上月（示例）')}</p><svg viewBox="0 0 140 38" class="sparkline" aria-hidden="true"><path d="m2 32 23-16 24 8 23-18 23 7 22-9 21-3"/></svg></div><div class="panel stat-card"><span>${L('広告傘の利用回数','广告伞借用次数')}${icon('umbrella')}</span><strong>2,340<small>${L('回','次')}</small></strong><p><b>+9.3%</b> ${L('前月比（サンプル）','较上月（示例）')}</p><svg viewBox="0 0 140 38" class="sparkline" aria-hidden="true"><path d="m2 32 22-9 22 5 24-20 22 8 24-12 23-2"/></svg></div><div class="panel stat-card"><span>${L('広告傘設置スポット','广告伞投放伞点')}${icon('pin')}</span><strong>32<small>${L('箇所','处')}</small></strong><p><b>+4</b> ${L('前月比（サンプル）','较上月（示例）')}</p></div></div><div class="ad-columns"><section class="panel campaigns"><div class="panel-title"><h2>${L('掲載中の広告','正在投放的广告')}</h2>${labelDemo()}</div><article class="campaign"><div class="campaign-visual coffee-sponsor">${icon('coffee')}</div><div class="campaign-copy"><h3>${L('まちのカフェ｜雨の日クーポン','街角咖啡｜雨天优惠')}</h3><p>${L('掲載期間','投放时间')}：2026.10.01 – 2026.12.31</p><p>${L('掲載エリア','投放区域')}：${areas.slice(0,2).join(' / ')}</p></div><span class="status-pill">${L('掲載中','投放中')}</span></article><article class="campaign"><div class="campaign-visual green-sponsor">${icon('store')}</div><div class="campaign-copy"><h3>${L('世田谷ショップ｜街のお買いもの','世田谷小店｜社区购物')}</h3><p>${L('掲載期間','投放时间')}：2026.10.01 – 2026.11.30</p><p>${L('掲載エリア','投放区域')}：${areas[2]}</p></div><span class="status-pill">${L('掲載中','投放中')}</span></article></section><section class="panel area-panel"><h2>${L('掲載エリア','投放区域')}</h2><p>${L('3つのエリアで地域とつながる','在三个区域连接社区')}</p>${areas.map((a,i)=>`<div class="area-row">${icon(['university','train','store'][i])}<span>${a}</span><strong>${[14,12,6][i]}<small>${L('箇所','处')}</small></strong></div>`).join('')}<span class="muted note">${L('設置数はサンプルです','伞点数量为示例')}</span></section></div><section class="panel application-list"><div class="panel-title"><h2>${L('掲載申請の下書き','广告申请草稿')}</h2><span class="count-badge">${state.applications.length}</span></div>${state.applications.length?state.applications.map(a=>`<div class="application-row"><div><strong>${esc(a.company)} · ${esc(a.title)}</strong><small>${esc(a.start)} – ${esc(a.end)} · ${a.areas.map(k=>({university:areas[0],station:areas[1],shop:areas[2]})[k]).join(' / ')}</small></div><span class="draft-badge">${L('ローカル下書き','本地草稿')}</span></div>`).join(''):`<div class="empty-state compact"><p>${L('掲載したい広告を、申請フォームから登録できます。','点击申请广告投放，填写并保存你的方案。')}</p></div>`}</section>`;}

function render(){const r=route();let page=r.page;const renderers={home,qr:qrPage,station:()=>stationPage(r.params.get('spot')),spots:()=>spotsPage(),borrow:()=>borrowPage(r.params.get('spot')),rental:rentalPage,borrowed:borrowedPage,return:()=>state.active?spotsPage('return'):rentalPage(),complete:()=>completePage(r.params.get('id')),profile:profilePage,services:servicesPage,advertiser:advertiserPage};if(!renderers[page])page='home';root.innerHTML=shell(renderers[page](),page);document.documentElement.lang=({ja:'ja',zh:'zh-CN',en:'en'})[state.lang];document.title=`${L('レインフロー・アズ','Rain Flow As 共享借伞')} | Rain Flow As 3.0`;}
function openDialog(content,wide=false){closeCamera();verifiedAuth=null;dialog.className=wide?'wide-dialog':'';dialog.innerHTML=`<button class="dialog-close icon-btn" data-action="close-dialog" aria-label="${L('閉じる','关闭')}">${icon('x')}</button>${content}`;if(!dialog.open)dialog.showModal();}
function closeDialog(){closeCamera();verifiedAuth=null;dialog.close();returnTarget=null;}
function login(register=false){openDialog(`<div class="dialog-brand">${icon('umbrella')}<span>Rain Flow As</span></div><p class="eyebrow">WELCOME TO RAIN FLOW AS.</p><h2 id="dialog-title">${register?L('はじめまして。','你好，新朋友。'):L('おかえりなさい。','欢迎回来。')}</h2><div class="auth-tabs"><button class="${!register?'active':''}" data-action="login">${L('ログイン','登录')}</button><button class="${register?'active':''}" data-action="register">${L('新規登録','注册')}</button></div><div class="notice small-notice">${L('デモ用のフォームです。実際のパスワードは入力しないでください。','此为演示表单，请勿输入真实密码。')}</div><form id="login-form">${register?`<label>${L('お名前','昵称')}<input name="name" required maxlength="40" placeholder="${L('雨の日さん','雨天旅人')}"></label>`:''}<label>${L('メールアドレス（デモ）','邮箱（演示）')}<input type="email" name="email" required value="demo@rainflow.example" autocomplete="off"></label><label>${L('パスワード（デモ）','密码（演示）')}<input name="password" type="password" required minlength="6" value="demo2026" autocomplete="off"></label><button type="submit" class="btn primary full">${register?L('デモプロフィールを作成','创建演示资料'):L('デモでログイン','登录演示账号')}${icon('arrow')}</button><p class="form-caption">${L('本番の認証は行いません。パスワードは保存しません。','不会进行真实认证，也不会保存密码。')}</p></form><div class="line-coming"><b>LINE</b><span>${L('LINE連携は検討中','LINE 登录规划中')}</span></div>`);}
function editProfile(){const p=state.profile;openDialog(`<p class="eyebrow">YOUR PROFILE</p><h2 id="dialog-title">${L('プロフィールを編集','编辑个人资料')}</h2><p class="dialog-description">${L('このブラウザだけに保存する、体験用プロフィールです。','演示资料仅保存在当前浏览器。')}</p><form id="profile-form"><div class="form-grid"><label>${L('お名前','昵称')}<input name="name" required maxlength="40" value="${esc(p.name)}" placeholder="${L('雨の日さん','雨天旅人')}"></label><label>${L('ふりがな（任意）','姓名假名（选填）')}<input name="kana" maxlength="60" value="${esc(p.kana)}"></label></div><div class="form-grid"><label>${L('年齢（任意）','年龄（选填）')}<input type="number" name="age" min="1" max="120" value="${esc(p.age)}"></label><label>${L('お住まいのエリア（任意）','所在区域（选填）')}<input name="address" maxlength="80" placeholder="${L('世田谷区','世田谷区')}" value="${esc(p.address)}"></label></div><fieldset><legend>${L('趣味・関心','兴趣爱好')}</legend><div class="checkbox-chips">${[['music',L('音楽','音乐')],['reading',L('読書','阅读')],['drive',L('ドライブ','自驾')],['walking',L('散歩','散步')]].map(([id,t])=>`<label><input type="checkbox" name="interests" value="${id}" ${p.interests?.includes(id)?'checked':''}><span>${t}</span></label>`).join('')}</div></fieldset><button class="btn primary full" type="submit">${L('保存する','保存资料')}${icon('check')}</button></form>`);}

function scanner(id,mode){const s=spot(id);openDialog(`<p class="eyebrow">SCAN THE STATION QR.</p><h2 id="dialog-title">${mode==='return'?L('QRから返却登録','扫码登记归还','Scan to register a return'):L('QRから貸出登録','扫码登记借用','Scan to register a loan')}</h2><p class="dialog-description">${icon('pin')}${esc(name(s))}</p>${formSteps(1)}<div class="scan-frame"><video id="camera-video" autoplay muted playsinline></video><div id="scan-placeholder">${icon('qr')}<span>${L('貸出・返却共用のQRを枠内へ','将借还共用二维码放入框内','Place the shared station QR inside the frame')}</span></div><i class="corner c1"></i><i class="corner c2"></i><i class="corner c3"></i><i class="corner c4"></i></div><p id="scan-status" class="form-caption" role="status">${L('カメラでQRを読むか、QR画像を選んでください。','开启摄像头扫码，或选择二维码图片。','Use your camera, or choose an image of the QR code.')}</p>${btn(icon('camera')+L('カメラで読み取る','开启摄像头扫码','Scan with camera'),'camera','primary full',`data-id="${id}" data-mode="${mode}"`)}<label class="btn secondary full qr-upload">${icon('qr')}${L('QR画像を読み込む','识别二维码图片','Choose a QR image')}<input type="file" id="qr-photo" accept="image/*" data-id="${id}" data-mode="${mode}"></label>${btn(L('デモQRで試す','使用演示码体验','Try the demo QR'),'demo-scan','ghost full',`data-id="${id}" data-mode="${mode}"`)}<details class="manual-code"><summary>${L('読み取れない場合：コード入力','无法扫码？手动输入编码','Cannot scan? Enter the station code')}</summary><form id="code-form" data-id="${id}" data-mode="${mode}"><label>${L('スポットコード','伞点编码','Station code')}<div class="code-input"><input name="code" required autocomplete="off" autocapitalize="characters" placeholder="${s.code}"><button type="submit" class="btn secondary">${L('確認','确认','Check')}</button></div></label><p class="form-caption">${L('デモコード','演示码','Demo code')}：${s.code}</p></form></details><p class="form-caption">${L('読取だけでは貸出・返却は完了しません。次の登録フォームを送信してください。','扫描成功后还需提交登记表，才会完成借用或归还。','Scanning alone does not complete a loan or return. Submit the registration form next.')}</p>`);returnTarget={id,mode};}
function confirmScan(id,mode,method='qr-demo'){
 closeCamera();const s=spot(id),ret=mode==='return',a=state.active;
 if(ret&&!a)throw Error('inactive');if(!ret&&a)throw Error('active');
 const person=ret?(a.borrowRegistration||state.profile):state.profile,date=localDate(ret?rentalNow(a):Date.now());
 openDialog(`<div class="registration-form-header"><span class="form-brand">Rain Flow As <b>3.0</b></span><h2 id="dialog-title">${ret?L('返却登録フォーム','归还登记表','Return registration'):L('貸出登録フォーム','借用登记表','Loan registration')}</h2><p>${esc(name(s))}</p></div>${formSteps(2)}<div class="auth-verified">${icon('check')}${methodName(method)} · ${L('スポット確認済み','伞点已确认','Station confirmed')}</div>${formNotice()}<form id="${ret?'return-registration-form':'loan-registration-form'}" data-id="${id}"><label>${L('学籍番号（必須）','学号（必填）','Student ID (required)')}<input name="studentId" required maxlength="40" value="${esc(person.studentId||'')}" placeholder="24-7A155" autocomplete="off"></label><label>${L('名前（必須）','姓名（必填）','Name (required)')}<input name="name" required maxlength="80" value="${esc(person.name||'')}" placeholder="${L('お名前','你的姓名','Your name')}" autocomplete="name"></label>${ret?'':`<label>${L('メールアドレス（必須）','邮箱（必填）','Email (required)')}<input name="email" type="email" required maxlength="160" value="${esc(person.email||'')}" placeholder="student@example.com" autocomplete="email"></label>`}<label>${ret?L('返却日','归还日期','Return date'):L('貸出日','借用日期','Loan date')}<input type="date" name="date" readonly value="${date}" aria-readonly="true"></label>${ret?`<label>${L('傘の状態（必須）','雨伞状态（必填）','Umbrella condition (required)')}<select id="return-condition" name="condition" required><option value="normal" ${!a.damageReported?'selected':''}>${L('正常','完好','Good condition')}</option><option value="damaged" ${a.damageReported?'selected':''}>${L('破損あり','损坏','Damaged')}</option></select></label><label>${L('補足（任意）','补充说明（选填）','Notes (optional)')}<textarea name="note" maxlength="1000" rows="2">${esc(a.damageNote||'')}</textarea></label><div id="return-cost">${returnCostMarkup()}</div>`:`<div class="confirm-deadline">${icon('calendar')}<div><span>${L('返却期限（貸出期間1週間）','归还期限（借用一周）','Return due date (one-week loan)')}</span><strong>${stamp(Date.now()+LOAN_MS)}</strong></div></div>${policyBox()}`}<label class="consent-label"><input name="accepted" type="checkbox" required><span>${ret?L('傘をスポットへ戻し、登録内容と弁償代の表示を確認しました。','已将雨伞放回伞点，并确认登记信息及显示的赔偿金额。','I have put the umbrella back and checked the registration details and any compensation shown.'):L('1週間の貸出期間と、期限超過・破損時の弁償代2,000円を確認しました。','已了解一周借用期限，以及逾期未还或损坏时 2,000 日元的赔偿规则。','I understand the one-week loan period and the ¥2,000 compensation for an overdue or damaged umbrella.')}</span></label><p id="confirm-error" class="form-error" role="alert"></p><button type="submit" class="btn primary full">${ret?L('返却登録を送信（デモ）','提交归还登记（演示）','Submit return (demo)'):L('貸出登録を送信（デモ）','提交借用登记（演示）','Submit loan (demo)')}${icon('arrow')}</button><p class="form-caption">${L('デモ用の情報でお試しください。Googleへの送信はありません。','请使用示例信息体验，不会向 Google 发送数据。','Please use sample details. No data is sent to Google.')}</p></form>${btn(L('キャンセル','取消','Cancel'),'close-dialog','ghost full')}`);
 verifiedAuth={id,mode,method,rentalId:a?.id,expiresAt:Date.now()+1800000};
}
function acceptQr(raw,id,mode,method){const found=qrSpotId(raw,[SITE_ORIGIN,currentOrigin()]);if(found!==id){document.getElementById('scan-status').textContent=L('選択したスポットのQRではありません。正しいスポットのQRを読み取ってください。','二维码与当前伞点不匹配，请扫描正确伞点的二维码。','This QR does not match the selected station. Scan that station’s QR code.');return false;}confirmScan(id,mode,method);return true;}
async function scanPhoto(input){const file=input.files?.[0];if(!file)return;const target=returnTarget,request=cameraRequest;if(!target)return;const status=document.getElementById('scan-status');status.textContent=L('QR画像を読み取っています…','正在识别二维码图片…','Reading QR image…');const image=new Image(),url=URL.createObjectURL(file);try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});if(!dialog.open||request!==cameraRequest)return;const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,canvas.width,canvas.height);const data=ctx.getImageData(0,0,canvas.width,canvas.height),result=jsQR(data.data,data.width,data.height);if(result)acceptQr(result.data,target.id,target.mode,'qr-photo');else status.textContent=L('QRを検出できませんでした。鮮明な画像を選ぶか、コードを入力してください。','未识别到二维码，请使用清晰图片或手动输入编码。','No QR was found. Choose a clearer image or enter the station code.');}catch{if(dialog.open)status.textContent=L('画像を読み込めませんでした。PNG・JPEGなどの画像をお試しください。','无法读取图片，请尝试 PNG 或 JPEG 图片。','The image could not be read. Try a PNG or JPEG image.');}finally{URL.revokeObjectURL(url);}}
async function startCamera(id,mode){const status=document.getElementById('scan-status');if(!navigator.mediaDevices?.getUserMedia){status.textContent=L('カメラを使えません。QR画像の読込・コード入力・デモ読取をご利用ください。','摄像头不可用，请选择二维码图片、输入编码或使用演示码。','Camera access is unavailable. Choose a QR image, enter the code, or try the demo.');return;}if(cameraStream)return;const request=++cameraRequest;try{status.textContent=L('カメラを準備しています…','正在开启摄像头…','Starting camera…');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(!dialog.open||request!==cameraRequest){stream.getTracks().forEach(t=>t.stop());return;}const video=document.getElementById('camera-video');cameraStream=stream;video.srcObject=stream;video.style.display='block';document.getElementById('scan-placeholder').style.display='none';await video.play();if(request!==cameraRequest)return;const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});status.textContent=L('QRコードを枠内に合わせてください。','请将二维码放入取景框。','Place the QR code inside the frame.');scanTimer=setInterval(()=>{if(scanBusy||!cameraStream||video.readyState<2||request!==cameraRequest)return;scanBusy=true;try{const scale=Math.min(1,800/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);ctx.drawImage(video,0,0,canvas.width,canvas.height);const data=ctx.getImageData(0,0,canvas.width,canvas.height),code=jsQR(data.data,data.width,data.height,{inversionAttempts:'dontInvert'});if(code&&dialog.open)acceptQr(code.data,id,mode,'qr-camera');}catch{}finally{scanBusy=false;}},350);}catch{if(request!==cameraRequest)return;closeCamera();if(dialog.open)document.getElementById('scan-status').textContent=L('カメラを利用できません。画像読込・コード入力をお試しください。','无法使用摄像头，请上传二维码图片或输入编码。','The camera could not be opened. Choose a QR image or enter the code.');}}
function closeCamera(){cameraRequest++;if(scanTimer)clearInterval(scanTimer);scanTimer=null;if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;scanBusy=false;}
function offer(id){const c=id==='coffee',saved=state.coupons.some(i=>i.id===id);openDialog(`<div class="coupon-hero ${c?'coffee-sponsor':'green-sponsor'}">${icon(c?'coffee':'gift')}<span>RAINY DAY, HAPPY DAY.</span></div><p class="eyebrow">LOCAL PARTNER / DEMO</p><h2 id="dialog-title">${c?L('雨の日に、ひと息どうぞ。','下雨了，停下来喝一杯吧。'):L('まちのお店から、小さなお得。','来自街角小店的小惊喜。')}</h2><div class="offer-value">${c?'¥50<span>OFF</span>':'10%<span>OFF</span>'}</div><p>${c?L('お好きなドリンク1杯に使える、体験用クーポン。','任意一杯饮品可用的演示优惠券。'):L('お買いものに使える、体験用クーポン。','用于体验购物流程的演示优惠券。')}</p><div class="info-box"><strong>${L('デモ専用クーポン','演示专用优惠券')}</strong><p>${L('実店舗での割引や交換はできません。保存・使用済みへの切り替えを体験できます。','无法在真实门店抵扣或兑换，可以体验领取及模拟使用流程。')}</p></div>${btn(saved?L('保存済み・クーポンを見る','已领取 · 查看优惠券'):L('クーポンを保存','领取优惠券'),saved?'open-services':'save-coupon','primary full',`data-id="${id}"`)}`);}
function adForm(){openDialog(`<p class="eyebrow">GROW WITH YOUR NEIGHBORHOOD.</p><h2 id="dialog-title">${L('広告掲載の申請','申请广告投放')}</h2><p class="dialog-description">${L('デモ申請は下書きとしてこのブラウザに保存されます。送信はされません。','演示申请将保存为本地草稿，不会发送给任何人。')}</p><form id="ad-form"><label>${L('企業・店舗名','企业 / 门店名称')}<input name="company" required maxlength="80" placeholder="${L('例：世田谷カフェ','例如：世田谷咖啡')}"></label><label>${L('広告・キャンペーン名','广告 / 活动名称')}<input name="title" required maxlength="120" placeholder="${L('例：雨の日ドリンクキャンペーン','例如：雨天饮品优惠')}"></label><div class="form-grid"><label>${L('掲載開始日','投放开始日期')}<input type="date" name="start" required></label><label>${L('掲載終了日','投放结束日期')}<input type="date" name="end" required></label></div><fieldset><legend>${L('希望エリア（1つ以上）','意向区域（至少一项）')}</legend><div class="checkbox-chips">${[['university',L('大学周辺','大学周边')],['station',L('駅周辺','车站周边')],['shop',L('商業施設','商业设施')]].map(([id,n])=>`<label><input type="checkbox" name="areas" value="${id}"><span>${n}</span></label>`).join('')}</div></fieldset><label>${L('広告の内容・ご要望','广告内容 / 其他要求')}<textarea name="description" maxlength="1000" rows="3"></textarea></label><p class="form-error" id="ad-error" role="alert"></p><button type="submit" class="btn primary full">${L('申請の下書きを保存','保存申请草稿')}${icon('arrow')}</button></form>`);}

async function locate(){if(!navigator.geolocation){toast(L('位置情報に対応していません。デモ位置をご利用ください。','当前浏览器不支持定位，将继续使用演示位置。'));return;}toast(L('位置情報を取得しています…','正在获取位置…'));navigator.geolocation.getCurrentPosition(p=>{geo={lat:p.coords.latitude,lng:p.coords.longitude};render();toast(L('GPS位置からデモスポットまでの距離を表示しました。','已按 GPS 位置计算与演示伞点的距离。'));},()=>toast(L('現在地を取得できません。世田谷のデモ位置を使用します。','无法获取定位，继续使用世田谷演示位置。')),{timeout:10000,maximumAge:60000,enableHighAccuracy:false});}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const {action,id,value,mode}=el.dataset;
 try{switch(action){
  case 'language':commit({...state,lang:['ja','zh','en'].includes(value)?value:['ja','zh','en'][(['ja','zh','en'].indexOf(state.lang)+1)%3]});closeDialog();render();break;
  case 'rules':rules();break;
  case 'station-borrow':confirmScan(id,'borrow','qr-link');break;
  case 'station-return':confirmScan(id,'return','qr-link');break;
  case 'qr-select':qrSelected=id;render();break;
  case 'qr-download':downloadQr(id,currentOrigin(),value);break;
  case 'qr-copy':{const url=stationUrl(qrSelected,currentOrigin());if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url).then(()=>toast(L('リンクをコピーしました。','链接已复制。','Link copied.'))).catch(()=>toast(L('リンク欄からコピーしてください。','请从链接输入框中复制。','Please copy the address from the link field.')));else toast(L('リンク欄からコピーしてください。','请从链接输入框中复制。','Please copy the address from the link field.'));break;}
  case 'damage':damageDialog();break;
  case 'clear-damage':commit(clearDamage(state));closeDialog();render();toast(L('破損申告を取り消しました。','已撤销损坏申报。'));break;
  case 'overdue-demo':commit(setOverdueDemo(state,!state.active.demoOverdue));render();break;
  case 'help':help();break;case 'close-dialog':closeDialog();break;case 'login':login();break;case 'register':login(true);break;case 'edit-profile':editProfile();break;
  case 'logout':commit({...state,profile:freshState().profile});render();toast(L('デモプロフィールからログアウトしました。履歴はこのブラウザに残ります。','已退出演示资料，借用记录仍保留在当前浏览器。'));break;
  case 'favorite':commit(toggleFavorite(state,id));render();break;
  case 'detail':go(`borrow?spot=${id}`);break;case 'back-spots':go('spots');break;
  case 'borrow-near':go(`borrow?spot=${nearby().find(s=>state.inventory[s.id]>0)?.id||'koku'}`);break;
  case 'return-list':filter='available';query='';go('return');break;
  case 'choose-return':if(!state.active){go('rental');break;}if(returnSlots(state,id)<1)throw Error('full');scanner(id,'return');break;
  case 'auth-borrow':case 'scan-borrow':if(state.active)throw Error('active');if(state.inventory[id]===0)throw Error('empty');scanner(id,'borrow');break;
  case 'demo-scan':confirmScan(id,mode,'qr-demo');break;case 'camera':startCamera(id,mode);break;
  case 'history':rating=0;go(`complete?id=${id}`);break;
  case 'rate':rating=Number(value);document.querySelectorAll('.star').forEach((b,i)=>{b.classList.toggle('filled',i<rating);b.setAttribute('aria-pressed',i+1===rating?'true':'false');});break;
  case 'filter':filter=value;render();break;case 'view':view=value;render();break;
  case 'map-open':view='map';go('spots');break;
  case 'map-select':selectedMap=id;if(route().page==='home')go(`borrow?spot=${id}`);else render();break;
  case 'clear-filters':filter='all';query='';render();break;case 'locate':locate();break;
  case 'offer':offer(id);break;
  case 'save-coupon':if(!state.coupons.some(c=>c.id===id))commit({...state,coupons:[...state.coupons,{id,used:false}]});closeDialog();go('services');toast(L('クーポンを保存しました（デモ）。','已领取优惠券（演示）。'));break;
  case 'open-services':closeDialog();go('services');break;
  case 'use-coupon':commit({...state,coupons:state.coupons.map(c=>c.id===id?{...c,used:true}:c)});render();toast(L('クーポンを使用済みにしました（デモ）。','已模拟使用优惠券。'));break;
  case 'ad-application':adForm();break;
  case 'reset-prompt':openDialog(`<div class="dialog-icon">${icon('settings')}</div><h2 id="dialog-title">${L('デモデータをリセットしますか？','重置演示数据？')}</h2><p class="dialog-description">${L('このブラウザのプロフィール、利用中の傘、履歴、評価、お気に入り、クーポン、広告申請の下書きを削除し、在庫を初期状態に戻します。','将清除当前浏览器内的资料、借用、记录、评价、收藏、优惠券和广告草稿，并重置库存。')}</p>${btn(L('リセットする','确认重置'),'reset','danger full')}${btn(L('キャンセル','取消'),'close-dialog','ghost full')}`);break;
  case 'reset':{const lang=state.lang;commit({...freshState(),lang});query='';filter='all';rating=0;geo=null;closeDialog();go('home');toast(L('デモを初期状態に戻しました。','演示数据已重置。'));break;}
 }}catch(err){error(err);}
});
document.addEventListener('input',e=>{if(e.target.id==='spot-search'){query=e.target.value;document.getElementById('spots-results').innerHTML=spotResults(route().page==='return'?'return':'borrow');if(view==='map'&&document.getElementById('spot-map'))document.getElementById('spot-map').innerHTML=mapPanel(true);}});
document.addEventListener('submit',e=>{const form=e.target;const known=['loan-registration-form','return-registration-form','damage-form','login-form','profile-form','code-form','rating-form','ad-form'];if(!known.includes(form.id))return;e.preventDefault();const d=new FormData(form);try{
 if(form.id==='loan-registration-form'||form.id==='return-registration-form'){
  const ret=form.id==='return-registration-form',id=form.dataset.id,method=verifiedMethod(id,ret?'return':'borrow');
  const fields={studentId:d.get('studentId'),name:d.get('name'),email:d.get('email'),condition:d.get('condition'),note:d.get('note'),accepted:!!d.get('accepted')};
  try{if(ret){commit(registerReturn(state,id,fields,Date.now(),method));rating=0;closeDialog();go(`complete?id=${state.history[0].id}`);}else{commit(registerLoan(state,id,fields,Date.now(),method));closeDialog();go('borrowed');}}catch(e){const messages={studentId:L('学籍番号を入力してください。','请填写学号。','Enter your student ID.'),registrationName:L('名前を入力してください。','请填写姓名。','Enter your name.'),registrationEmail:L('有効なメールアドレスを入力してください。','请填写有效邮箱。','Enter a valid email address.'),studentMismatch:L('貸出登録と同じ学籍番号を入力してください。','请填写与借用登记一致的学号。','Use the student ID from the loan registration.'),condition:L('傘の状態を選んでください。','请选择雨伞状态。','Select the umbrella condition.'),consent:L('利用条件と登録内容を確認し、チェックしてください。','请确认使用规则及登记信息，并勾选确认。','Review the rules and registration details, then check the box.')};if(messages[e.message])document.getElementById('confirm-error').textContent=messages[e.message];else throw e;}
 }
 if(form.id==='damage-form'){commit(reportDamage(state,String(d.get('note')||'')));closeDialog();render();toast(L('破損を記録しました（デモ）。まだ返却は完了していません。','已记录损坏（演示），尚未完成归还。'));}
 if(form.id==='login-form'){commit({...state,profile:{...state.profile,name:String(d.get('name')||'').trim()||L('雨の日さん','雨天旅人'),email:String(d.get('email'))}});closeDialog();render();toast(L('デモプロフィールでログインしました。','已登录演示资料。'));}
 if(form.id==='profile-form'){const n=String(d.get('name')).trim();if(!n){toast(L('お名前を入力してください。','请输入昵称。'));return;}commit({...state,profile:{...state.profile,name:n,kana:String(d.get('kana')||'').trim(),age:String(d.get('age')||''),address:String(d.get('address')||'').trim(),interests:d.getAll('interests')}});closeDialog();render();toast(L('プロフィールを保存しました。','资料已保存。'));}
 if(form.id==='code-form'){if(!matchesCode(form.dataset.id,d.get('code'))){document.getElementById('scan-status').textContent=L('コードが一致しません。表示されたデモコードを入力してください。','编码不匹配，请输入界面上显示的演示码。');return;}confirmScan(form.dataset.id,form.dataset.mode,'code');}
 if(form.id==='rating-form'){const id=form.dataset.id,h=state.history.find(h=>h.id===id);commit(rateRental(state,id,rating||h.rating,String(d.get('feedback')||'')));rating=0;toast(L('ご協力ありがとうございます。評価を保存しました。','感谢反馈，评价已保存。'));render();}
 if(form.id==='ad-form'){const areas=d.getAll('areas'),start=String(d.get('start')),end=String(d.get('end')),company=String(d.get('company')).trim(),title=String(d.get('title')).trim();let issue='';if(!company||!title)issue=L('企業名と広告名を入力してください。','请输入企业名称及广告名称。');else if(end<start)issue=L('終了日は開始日以降にしてください。','结束日期不能早于开始日期。');else if(!areas.length)issue=L('掲載エリアを1つ以上選んでください。','请至少选择一个投放区域。');if(issue){document.getElementById('ad-error').textContent=issue;return;}commit({...state,applications:[{id:'ad-'+Date.now(),company,title,start,end,areas,description:String(d.get('description')||'')},...state.applications]});closeDialog();render();toast(L('申請の下書きを保存しました。外部には送信していません。','申请草稿已保存，未向外部发送。'));}
}catch(err){error(err);}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
dialog.addEventListener('close',()=>{closeCamera();verifiedAuth=null;});dialog.addEventListener('cancel',()=>{closeCamera();verifiedAuth=null;});
document.addEventListener('change',e=>{if(e.target.id==='return-condition'){document.getElementById('return-cost').innerHTML=returnCostMarkup(e.target.value==='damaged');}if(e.target.id==='qr-photo')scanPhoto(e.target);});
window.addEventListener('hashchange',()=>{closeDialog();render();window.scrollTo({top:0,behavior:'instant'});document.getElementById('main-content').focus({preventScroll:true});});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){state=readState(storage);closeDialog();render();}});
